'use strict';

const $ = (selector, scope = document) => scope.querySelector(selector);
const $$ = (selector, scope = document) => [...scope.querySelectorAll(selector)];
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const state = {user:null,view:'dashboard',leads:[],users:[],appointments:[],conversations:[],settings:null,conversation:null,requestId:0};
const stages = {nuevo:'Nuevo',contactado:'Contactado',calificado:'Calificado',cita:'Cita',ganado:'Ganado',perdido:'Perdido'};
const views = {dashboard:'Panel',leads:'Prospectos',appointments:'Agenda',conversations:'Conversaciones',automation:'R.E.I.G.E.L.',marketing:'Marketing',settings:'Equipo y ajustes'};
const channels = {web:'Chat web propio',whatsapp:'WhatsApp',telegram:'Telegram',instagram:'Instagram',messenger:'Messenger',openai:'Inteligencia artificial',ai:'IA local'};
const statuses = {confirmed:'Confirmada',cancelled:'Cancelada',sent:'Enviado',failed:'Falló el envío',uncertain:'Entrega sin confirmar',received:'Recibido',pending:'Pendiente'};
const weekdays = ['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];
const content = $('#view-content');
const dialog = $('#form-dialog');
let toastTimer;
let lastDialogTrigger;

function timezone() { return state.settings?.business?.timezone || 'America/Puerto_Rico'; }
function dateTime(value, options = {}) {
  if (!value) return '—';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '—';
  return new Intl.DateTimeFormat('es-PR',{timeZone:timezone(),day:'numeric',month:'short',hour:'numeric',minute:'2-digit',...options}).format(date);
}
function time(value, zone = timezone()) { return new Intl.DateTimeFormat('es-PR',{timeZone:zone,hour:'numeric',minute:'2-digit'}).format(new Date(value)); }
function dateInput(offset = 0) {
  const date = new Date(Date.now() + offset * 86400000);
  return new Intl.DateTimeFormat('en-CA',{timeZone:timezone(),year:'numeric',month:'2-digit',day:'2-digit'}).format(date);
}
function initials(name) {return String(name || 'PS').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();}
function badge(value, label = null) {return `<span class="badge ${esc(value)}">${esc(label || stages[value] || statuses[value] || value)}</span>`;}
function errorMessage(data) {
  if (typeof data?.detail === 'string') return data.detail;
  if (Array.isArray(data?.detail)) return data.detail.map(item=>`${item.loc?.at(-1) || 'Campo'}: ${item.msg || 'valor inválido'}`).join('. ');
  return 'No se pudo completar la solicitud. Intenta nuevamente.';
}
async function api(path, options = {}) {
  const controller = new AbortController();
  const timeout = setTimeout(()=>controller.abort(),60000);
  try {
    const response = await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers},signal:controller.signal});
    const data = await response.json().catch(()=>({}));
    if (!response.ok) {
      if(response.status===401 && path!=='/api/auth/login') showLogin();
      const error = new Error(errorMessage(data)); error.status=response.status; throw error;
    }
    return data;
  } catch(error) {
    if (error.name==='AbortError') throw new Error('La solicitud tardó demasiado. Comprueba el estado antes de repetir un envío.');
    if (error instanceof TypeError) throw new Error('No hay conexión con el servidor. Comprueba que la app esté iniciada.');
    throw error;
  } finally { clearTimeout(timeout); }
}
function post(path,data,method='POST') {return api(path,{method,body:JSON.stringify(data)});}
function toast(message) {clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
function empty(title, text, action = '', symbol = '↗') {return `<div class="empty-state"><span class="empty-symbol" aria-hidden="true">${symbol}</span><h3>${esc(title)}</h3><p>${esc(text)}</p>${action}</div>`;}
function heading(kicker,title,copy,action='') {return `<div class="page-heading"><div><p class="eyebrow">${esc(kicker)}</p><h1>${esc(title)}</h1><p>${esc(copy)}</p></div>${action?`<div class="actions">${action}</div>`:''}</div>`;}
function actionButton(action,label,extra='',kind='primary') {return `<button type="button" class="button ${kind}" data-action="${esc(action)}" ${extra}>${esc(label)}</button>`;}
function loading() {return '<div class="loading" role="status">Cargando tu espacio…</div>';}
function fail(error) {content.innerHTML=`<div class="error-state" role="alert"><h2>No pudimos cargar esta vista.</h2><p>${esc(error.message)}</p>${actionButton('refresh','Volver a intentar')}</div>`;}
function showLogin() {state.user=null;$('#workspace').hidden=true;$('#login-screen').hidden=false;closeMenu();if(dialog.open)dialog.close();}
async function enter(user) {
  state.user=user;
  $('#login-screen').hidden=true;$('#workspace').hidden=false;
  $('#user-name').textContent=user.name;$('#user-role').textContent=user.role==='admin'?'Administrador':'Asesor';$('#user-avatar').textContent=initials(user.name);
  try {state.settings=await api('/api/settings');$('#business-zone').textContent=(state.settings.business?.market || 'Puerto Rico').toUpperCase();}catch {state.settings=null;}
  syncMenu();await navigate(state.view,false);
}
async function navigate(view, focus = true) {
  if (!views[view] || !state.user) return;
  state.view=view;state.conversation=null;const requestId=++state.requestId;
  closeMenu();$('#current-page').textContent=views[view];document.title=`${views[view]} · Power Solar`;
  $$('.nav-item').forEach(item=>{item.classList.toggle('active',item.dataset.view===view);if(item.dataset.view===view)item.setAttribute('aria-current','page');else item.removeAttribute('aria-current');});
  content.innerHTML=loading();
  if (focus) $('#main').focus();
  try {
    const renderers={dashboard:renderDashboard,leads:renderLeads,appointments:renderAppointments,conversations:renderConversations,automation:renderAutomation,marketing:renderMarketing,settings:renderSettings};
    await renderers[view](requestId);
  }catch(error){if(requestId===state.requestId&&state.user)fail(error);}
}
function current(requestId) {return requestId===state.requestId && !!state.user;}
async function loadUsers() {const data=await api('/api/team');state.users=data.users || [];return state.users;}
async function loadLeads() {const data=await api('/api/leads');state.leads=data.leads || [];return state.leads;}

async function renderDashboard(requestId) {
  const data=await api('/api/dashboard');if(!current(requestId))return;
  const metrics=data.metrics || {};
  const first=state.user.name.split(' ')[0];
  const stageCounts=Object.fromEntries((data.stages || []).map(item=>[item.stage,item.count]));
  const recent=data.recent_leads || [],upcoming=data.upcoming_appointments || [];
  content.innerHTML=heading('TU OPERACIÓN, EN PERSPECTIVA',`Hola, ${first}.`,'Cada contacto cuenta. Este es el pulso de tu equipo.',`<span class="today">${esc(new Intl.DateTimeFormat('es-PR',{timeZone:timezone(),weekday:'long',day:'numeric',month:'long'}).format(new Date()))}</span>${actionButton('new-lead','+ Nuevo prospecto')}`)+
    `<section class="welcome-banner"><h2>La próxima oportunidad<br>empieza con una conversación.</h2><p>Conecta tu página de captación con la agenda de tu equipo y da seguimiento a cada paso.</p><span class="banner-sun" aria-hidden="true"></span></section>
    <div class="metric-grid">${[
      ['PROSPECTOS',metrics.leads??0,'En tu cartera','◎'],['CITAS',metrics.appointments??0,'Registradas en la agenda','▦'],['CONVERSACIONES',metrics.conversations??0,'Recibidas en tus canales','☷'],['CONVERSIÓN',`${Number(metrics.conversion_rate??0).toFixed(1)}%`,'Ganados sobre prospectos','↗']
    ].map(([label,value,note,icon])=>`<article class="metric"><div class="metric-label">${label}<span aria-hidden="true">${icon}</span></div><strong>${esc(value)}</strong><small>${note}</small></article>`).join('')}</div>
    <div class="two-columns"><section class="panel"><header class="panel-head"><div><p class="section-kicker">DEL INTERÉS A LA DECISIÓN</p><h2>Tu recorrido comercial</h2></div><button class="text-link" data-view="leads" type="button">Ver prospectos ↗</button></header><div class="pipeline">${Object.entries(stages).map(([key,label])=>`<div class="pipeline-item"><span aria-hidden="true"></span><strong>${esc(stageCounts[key]??0)}</strong><small>${label}</small></div>`).join('')}</div><div class="section-separator"></div>${recent.length?`<ul class="row-list">${recent.slice(0,5).map(lead=>`<li><span class="avatar">${esc(initials(lead.name))}</span><div class="list-content"><button type="button" class="table-button" data-action="lead-detail" data-id="${esc(lead.id)}">${esc(lead.name)}</button><p>${esc(lead.municipality || 'Municipio por confirmar')} · ${esc(lead.source || 'Registro directo')}</p></div>${badge(lead.stage)}</li>`).join('')}</ul>`:empty('Tu próxima relación comienza aquí.','Añade un prospecto o comparte la página de captación para empezar.',actionButton('new-lead','Añadir mi primer prospecto','','small'))}</section>
    <section class="panel"><header class="panel-head"><div><p class="section-kicker">PRÓXIMOS ENCUENTROS</p><h2>En tu agenda</h2></div><button class="text-link" data-view="appointments" type="button">Ver agenda ↗</button></header>${upcoming.length?`<ul class="row-list">${upcoming.slice(0,5).map(appointment=>`<li>${dateTile(appointment.start_at)}<div class="list-content"><strong>${esc(appointment.lead_name || 'Evaluación solar')}</strong><p>${esc(time(appointment.start_at))} · ${esc(appointment.advisor_name || '')}</p></div></li>`).join('')}</ul>`:empty('Dale espacio a lo que sigue.','Las citas confirmadas aparecerán aquí. Define tu disponibilidad para recibir reservas.',`<button type="button" class="button small" data-view="settings">Configurar disponibilidad</button>`,'▦')}<div class="panel-body"><p class="hint">Las métricas se calculan con tus registros. Las reservas se confirman solo cuando hay un horario disponible.</p></div></section></div>`;
}
function dateTile(value) {const date=new Date(value);return `<div class="date-tile"><strong>${esc(new Intl.DateTimeFormat('es-PR',{timeZone:timezone(),day:'numeric'}).format(date))}</strong><span>${esc(new Intl.DateTimeFormat('es-PR',{timeZone:timezone(),month:'short'}).format(date))}</span></div>`;}

async function renderLeads(requestId) {
  await Promise.all([loadLeads(),loadUsers()]);if(!current(requestId))return;
  content.innerHTML=heading('RELACIONES CON FUTURO','Prospectos','El contexto correcto para dar el próximo paso.',actionButton('new-lead','+ Nuevo prospecto'))+
    `<div class="toolbar"><input type="search" id="lead-search" aria-label="Buscar prospectos" placeholder="Buscar por nombre, correo o municipio…"><select id="stage-filter" aria-label="Filtrar por etapa"><option value="">Todas las etapas</option>${Object.entries(stages).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select><span class="count" id="lead-count"></span></div><section class="panel" id="leads-result"></section>`;
  $('#lead-search').addEventListener('input',filterLeads);$('#stage-filter').addEventListener('change',filterLeads);filterLeads();
}
function filterLeads() {
  const query=($('#lead-search')?.value || '').trim().toLocaleLowerCase('es');const stage=$('#stage-filter')?.value || '';
  const leads=state.leads.filter(lead=>(!stage||lead.stage===stage)&&[lead.name,lead.email,lead.phone,lead.municipality].some(value=>String(value || '').toLocaleLowerCase('es').includes(query)));
  $('#lead-count').textContent=`${leads.length} ${leads.length===1?'prospecto':'prospectos'}`;
  $('#leads-result').innerHTML=leads.length?`<div class="table-wrap"><table><thead><tr><th>PROSPECTO</th><th>ETAPA</th><th>MUNICIPIO</th><th>ASESOR</th><th>ORIGEN</th><th>PERMISO</th></tr></thead><tbody>${leads.map(lead=>`<tr><td><button type="button" class="table-button" data-action="lead-detail" data-id="${esc(lead.id)}">${esc(lead.name)}</button><small>${esc(lead.email || lead.phone || 'Sin contacto')}</small></td><td>${badge(lead.stage)}</td><td>${esc(lead.municipality || '—')}</td><td>${esc(lead.advisor_name || state.users.find(user=>user.id===lead.advisor_id)?.name || 'Sin asignar')}</td><td>${esc(lead.source || 'Directo')}</td><td>${lead.consent?badge('green','Autorizado'):badge('orange','Sin autorización')}</td></tr>`).join('')}</tbody></table></div>`:empty(query||stage?'No hay coincidencias.':'Una cartera empieza con una persona.',query||stage?'Prueba otra búsqueda o etapa.':'Registra el primer contacto o comparte tu enlace de captación.',query||stage?'':actionButton('new-lead','+ Añadir prospecto','','small'),'◎');
}
function openDialog(title,html) {lastDialogTrigger=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal();}
function closeDialog() {dialog.close();if(lastDialogTrigger?.isConnected)lastDialogTrigger.focus();}
function formError(form,error) {const element=$('.form-error',form);if(element)element.textContent=error.message || String(error);}
async function submitForm(event,work) {
  event.preventDefault();const form=event.currentTarget;const button=$('[type=submit]',form);if(button?.disabled)return;
  const error=$('.form-error',form);if(error)error.textContent='';if(button)button.disabled=true;
  try {await work(form,new FormData(form));}catch(error){formError(form,error);}finally{if(button?.isConnected)button.disabled=false;}
}
function leadFields() {return `<div class="form-grid"><label class="span-2">Nombre completo<input name="name" required maxlength="120" autocomplete="name"></label><label>Correo electrónico<input name="email" type="email" maxlength="254" autocomplete="email"></label><label>Teléfono<input name="phone" type="tel" maxlength="30" autocomplete="tel" placeholder="+1 787…"></label><label>Municipio<input name="municipality" maxlength="100" autocomplete="address-level2"></label><label>Factura mensual aproximada (USD)<input name="monthly_bill" type="number" min="0" max="100000" step="0.01"></label><label class="span-2 checkbox"><input name="consent" type="checkbox"><span>La persona autorizó ser contactada por Power Solar. Registra solo un permiso real.</span></label></div><p class="field-help">Incluye al menos un correo o teléfono. Un registro sin permiso no autoriza mensajes comerciales.</p>`;}
async function newLead() {
  openDialog('Una nueva oportunidad',`<form id="lead-form">${leadFields()}<p class="form-error" role="alert"></p><div class="form-actions"><button class="button" type="button" data-action="close-dialog">Cancelar</button><button class="button primary" type="submit">Guardar prospecto</button></div></form>`);
  $('#lead-form').addEventListener('submit',event=>submitForm(event,async(form,data)=>{if(!data.get('email')&&!data.get('phone'))throw new Error('Incluye un correo electrónico o teléfono.');await post('/api/leads',{name:data.get('name'),email:data.get('email')||'',phone:data.get('phone')||'',municipality:data.get('municipality')||'',monthly_bill:data.get('monthly_bill')?Number(data.get('monthly_bill')):null,consent:data.has('consent'),source:'manual'});closeDialog();toast('Prospecto guardado.');await navigate(state.view,false);}));
}
async function leadDetail(id) {
  openDialog('Ficha del prospecto',loading());
  try {
    const [data]=await Promise.all([api(`/api/leads/${encodeURIComponent(id)}`),loadUsers()]);const lead=data.lead;
    $('#dialog-content').innerHTML=`<div class="detail-summary"><div><small>NOMBRE</small><p>${esc(lead.name)}</p></div><div><small>ETAPA</small><p>${badge(lead.stage)}</p></div><div><small>CORREO</small><p>${esc(lead.email || '—')}</p></div><div><small>TELÉFONO</small><p>${esc(lead.phone || '—')}</p></div><div><small>MUNICIPIO</small><p>${esc(lead.municipality || '—')}</p></div><div><small>FACTURA APROXIMADA</small><p>${lead.monthly_bill!=null?esc(new Intl.NumberFormat('es-PR',{style:'currency',currency:'USD'}).format(lead.monthly_bill)):'—'}</p></div><div><small>CONTACTO AUTORIZADO</small><p>${lead.consent?'Sí':'No registrado'}</p></div><div><small>ORIGEN</small><p>${esc(lead.source || 'Directo')}</p></div></div><form id="lead-update"><div class="form-grid"><label>Etapa<select name="stage">${Object.entries(stages).map(([key,label])=>`<option value="${key}" ${lead.stage===key?'selected':''}>${label}</option>`).join('')}</select></label>${state.user.role==='admin'?`<label>Asesor responsable<select name="advisor_id"><option value="">Sin asignar</option>${state.users.filter(user=>user.active!==false).map(user=>`<option value="${esc(user.id)}" ${lead.advisor_id===user.id?'selected':''}>${esc(user.name)}</option>`).join('')}</select></label>`:''}<label class="span-2">Notas de seguimiento<textarea name="notes" maxlength="4000">${esc(lead.notes || '')}</textarea></label></div><p class="form-error" role="alert"></p><div class="form-actions">${actionButton('schedule-lead','Agendar cita',`data-id="${esc(lead.id)}"`,'')}<button class="button primary" type="submit">Guardar cambios</button></div></form>${(data.appointments || []).length?`<div class="faq-compact"><h3>Citas del prospecto</h3>${data.appointments.map(item=>`<p class="status-inline">${esc(dateTime(item.start_at))} · ${esc(statuses[item.status] || item.status)}</p>`).join('')}</div>`:''}`;
    $('#lead-update').addEventListener('submit',event=>submitForm(event,async(form,fields)=>{const payload={stage:fields.get('stage'),notes:fields.get('notes')};if(state.user.role==='admin')payload.advisor_id=fields.get('advisor_id')||null;await post(`/api/leads/${encodeURIComponent(id)}`,payload,'PATCH');closeDialog();toast('Seguimiento actualizado.');await navigate(state.view,false);}));
  }catch(error){$('#dialog-content').innerHTML=`<p class="form-error" role="alert">${esc(error.message)}</p>`;}
}

async function renderAppointments(requestId) {
  const [data]=await Promise.all([api('/api/appointments'),loadLeads(),loadUsers()]);if(!current(requestId))return;state.appointments=data.appointments || [];
  content.innerHTML=heading('CADA ENCUENTRO, EN SU LUGAR','Agenda',`Citas en ${timezone()}. Las reservas evitan cruces de horarios y se confirman al guardarlas.`,actionButton('new-appointment','+ Agendar cita'))+
    `<div class="toolbar"><select id="appointment-filter" aria-label="Filtrar citas"><option value="upcoming">Próximas confirmadas</option><option value="all">Todas las citas</option><option value="cancelled">Canceladas</option></select><span class="count" id="appointment-count"></span></div><div id="appointments-result"></div>`;
  $('#appointment-filter').addEventListener('change',filterAppointments);filterAppointments();
}
function filterAppointments() {
  const filter=$('#appointment-filter').value;const appointments=state.appointments.filter(item=>filter==='all'||(filter==='cancelled'?item.status==='cancelled':item.status!=='cancelled'&&new Date(item.end_at || item.start_at)>new Date())).sort((a,b)=>new Date(a.start_at)-new Date(b.start_at));
  $('#appointment-count').textContent=`${appointments.length} ${appointments.length===1?'cita':'citas'}`;
  $('#appointments-result').innerHTML=appointments.length?`<div class="agenda-list">${appointments.map(item=>`<article class="appointment-card">${dateTile(item.start_at)}<div class="appointment-main"><h3>${esc(item.lead_name || 'Evaluación solar')}</h3><p>${esc(dateTime(item.start_at))}${item.end_at?` – ${esc(time(item.end_at))}`:''}</p><small>${esc(item.advisor_name || 'Asesor')} · ${esc(item.source || 'Agenda')}</small></div><div class="appointment-actions">${badge(item.status)}<a class="button small" href="/api/appointments/${encodeURIComponent(item.id)}/ics" download>Calendario ↓</a>${item.status!=='cancelled'?actionButton('cancel-appointment','Cancelar',`data-id="${esc(item.id)}"`,'small danger'):''}</div></article>`).join('')}</div>`:`<section class="panel">${empty('Tu agenda tiene espacio para crecer.','Configura la disponibilidad de tus asesores y comparte la página de captación para recibir citas.',actionButton('new-appointment','Agendar una cita','','small'),'▦')}</section>`;
}
async function newAppointment(leadId='') {
  openDialog('Agendar una evaluación',loading());
  try {
    await Promise.all([loadLeads(),loadUsers()]);const advisors=state.users.filter(user=>user.active!==false&&user.public_booking);
    if(!state.leads.length){$('#dialog-content').innerHTML=empty('Primero, un prospecto.','Registra el contacto antes de reservar una cita.',actionButton('new-lead','Crear prospecto','','small'));return;}
    if(!advisors.length){$('#dialog-content').innerHTML=empty('Define la disponibilidad primero.','Activa las reservas del asesor y su horario en Equipo y ajustes.','<button type="button" class="button small" data-action="availability">Ir a disponibilidad</button>','▦');return;}
    $('#dialog-content').innerHTML=`<form id="appointment-form"><div class="form-grid"><label class="span-2">Prospecto<select name="lead_id" required>${state.leads.map(lead=>`<option value="${esc(lead.id)}" ${lead.id===leadId?'selected':''}>${esc(lead.name)}</option>`).join('')}</select></label><label>Asesor<select id="appointment-advisor" name="advisor_id" required>${advisors.map(user=>`<option value="${esc(user.id)}">${esc(user.name)}</option>`).join('')}</select></label><label>Fecha<input type="date" id="appointment-date" required min="${dateInput()}" max="${dateInput(60)}" value="${dateInput(1)}"></label><div class="span-2"><label>Horario disponible<input type="hidden" id="appointment-start" name="start_at"></label><div id="appointment-slots" class="slots" role="group" aria-label="Horarios disponibles"></div><p id="appointment-zone" class="calendar-zone"></p></div></div><p class="form-error" role="alert"></p><div class="form-actions"><button class="button" data-action="close-dialog" type="button">Cancelar</button><button class="button primary" type="submit">Confirmar cita</button></div></form>`;
    const updateSlots=()=>loadSlots($('#appointment-advisor').value,$('#appointment-date').value,$('#appointment-slots'),$('#appointment-start'),$('#appointment-zone'));
    $('#appointment-advisor').addEventListener('change',updateSlots);$('#appointment-date').addEventListener('change',updateSlots);await updateSlots();
    $('#appointment-form').addEventListener('submit',event=>submitForm(event,async(form,data)=>{if(!data.get('start_at'))throw new Error('Selecciona un horario disponible.');await post('/api/appointments',{lead_id:data.get('lead_id'),advisor_id:data.get('advisor_id'),start_at:data.get('start_at')});closeDialog();toast('Cita confirmada en la agenda.');await navigate('appointments',false);}));
  }catch(error){$('#dialog-content').innerHTML=`<p class="form-error" role="alert">${esc(error.message)}</p>`;}
}
async function loadSlots(advisor,date,container,input,zoneElement) {
  input.value='';container.innerHTML='<p class="status-inline">Consultando horarios…</p>';const requestKey=`${advisor}-${date}`;container.dataset.request=requestKey;
  if(!advisor||!date){container.innerHTML='<p class="slot-empty">Elige un asesor y una fecha.</p>';return;}
  try {const data=await api(`/api/public/slots?advisor_id=${encodeURIComponent(advisor)}&date=${encodeURIComponent(date)}`);if(container.dataset.request!==requestKey)return;
    const zone=data.timezone || timezone();zoneElement.textContent=`Zona horaria: ${zone}`;
    container.innerHTML=(data.slots || []).length?data.slots.map(slot=>`<button type="button" class="slot-button" data-slot="${esc(slot.start_at)}" aria-pressed="false">${esc(time(slot.start_at,zone))}</button>`).join(''):'<p class="slot-empty span-2">No hay horarios disponibles para este día. Prueba otra fecha.</p>';
    $$('[data-slot]',container).forEach(button=>button.addEventListener('click',()=>{input.value=button.dataset.slot;$$('[data-slot]',container).forEach(other=>{other.classList.toggle('selected',other===button);other.setAttribute('aria-pressed',String(other===button));});}));
  }catch(error){if(container.dataset.request===requestKey)container.innerHTML=`<p class="form-error">${esc(error.message)}</p>`;}
}
async function cancelAppointment(id) {
  openDialog('Cancelar esta cita',`<p class="muted">El horario volverá a estar disponible. La cancelación se guarda en la agenda; avisa al prospecto por su canal habitual.</p><form id="cancel-form"><p class="form-error" role="alert"></p><div class="form-actions"><button class="button" data-action="close-dialog" type="button">Conservar cita</button><button class="button danger" type="submit">Confirmar cancelación</button></div></form>`);
  $('#cancel-form').addEventListener('submit',event=>submitForm(event,async()=>{await post(`/api/appointments/${encodeURIComponent(id)}`,{status:'cancelled'},'PATCH');closeDialog();toast('Cita cancelada.');await navigate('appointments',false);}));
}

async function renderConversations(requestId) {
  const [data]=await Promise.all([api('/api/conversations'),loadUsers()]);if(!current(requestId))return;state.conversations=data.conversations || [];
  content.innerHTML=heading('UNA BANDEJA. MÁS CONTEXTO.','Conversaciones','Atiende a cada persona, toma el control humano y activa la IA cuando corresponda.',actionButton('refresh','Actualizar bandeja','',''))+
    `<section class="conversation-layout"><div class="conversation-list"><div class="panel-head"><h2>Mensajes recibidos</h2><span class="badge">${state.conversations.length}</span></div>${state.conversations.length?state.conversations.map(item=>`<button type="button" class="conversation-choice" data-action="open-conversation" data-id="${esc(item.id)}"><strong>${esc(item.contact_name || 'Nuevo contacto')}</strong><small>${esc(channels[item.channel] || item.channel)} · ${item.mode==='ai'?'Atención automática':'Atención humana'}</small><p>${esc(item.last_message || 'Abrir conversación')}</p></button>`).join(''):empty('Aquí empieza la conversación.','Las conversaciones del chat web aparecen aquí. Comparte la página de captación para comenzar.','','☷')}</div><div class="conversation-main" id="conversation-detail">${empty('Personas, no solo mensajes.','Selecciona una conversación para revisar su contexto y responder.','','☷')}</div></section>`;
}
async function openConversation(id) {
  const container=$('#conversation-detail');if(!container)return;state.conversation=id;container.innerHTML=loading();$$('.conversation-choice').forEach(button=>button.classList.toggle('active',button.dataset.id===id));
  try {const data=await api(`/api/conversations/${encodeURIComponent(id)}`);if(state.conversation!==id||!container.isConnected)return;const item=data.conversation;const messages=data.messages || [];
    container.innerHTML=`<header class="conversation-head"><div><h2>${esc(item.contact_name || 'Nuevo contacto')}</h2><p>${esc(channels[item.channel] || item.channel)} · ${item.mode==='ai'?'R.E.I.G.E.L. atiende los próximos mensajes':'Atención humana'}</p></div><button class="button small ${item.mode==='ai'?'':'primary'}" type="button" data-action="conversation-mode" data-id="${esc(id)}" data-mode="${item.mode==='ai'?'human':'ai'}">${item.mode==='ai'?'Tomar control humano':'Activar atención automática'}</button></header>${state.user.role==='admin'?`<form id="conversation-assignment" class="panel-body"><label>Responsable<select name="advisor_id"><option value="">Sin asignar</option>${state.users.filter(user=>user.active!==false).map(user=>`<option value="${esc(user.id)}" ${item.advisor_id===user.id?'selected':''}>${esc(user.name)}</option>`).join('')}</select></label><div class="actions"><button class="button small" type="submit">Guardar responsable</button><p class="form-error" role="alert"></p></div></form>`:''}<div class="message-log" role="log" aria-label="Historial de la conversación">${messages.length?messages.map(message=>`<article class="message ${message.direction==='outbound'?'outbound':'inbound'}"><p class="message-text">${esc(message.text)}</p><small>${esc(dateTime(message.created_at))}${message.direction==='outbound'?` · ${esc(statuses[message.status] || message.status)}`:''}</small></article>`).join(''):empty('Todavía no hay mensajes.','El historial se conserva por conversación.','','☷')}</div><form class="composer" id="message-form"><label>Tu respuesta<textarea name="text" required maxlength="4000" aria-label="Tomar control humano: responder conversación" placeholder="Escribe una respuesta para esta persona…"></textarea></label><p class="form-error" role="alert"></p><div class="composer-footer"><small>Se envía por ${esc(channels[item.channel] || item.channel)}. Comprueba el estado de entrega.</small><button class="button primary small" type="submit">Enviar respuesta ↗</button></div></form>`;
    const log=$('.message-log',container);log.scrollTop=log.scrollHeight;
    $('#conversation-assignment')?.addEventListener('submit',event=>submitForm(event,async(form,fields)=>{await post(`/api/conversations/${encodeURIComponent(id)}`,{advisor_id:fields.get('advisor_id')||null},'PATCH');toast('Responsable actualizado.');}));
    $('#message-form').addEventListener('submit',event=>submitForm(event,async(form,fields)=>{await post(`/api/conversations/${encodeURIComponent(id)}/messages`,{text:fields.get('text')});toast(item.channel==='web'?'Respuesta guardada en el chat del cliente.':'Respuesta enviada al proveedor.');await openConversation(id);}));
  }catch(error){if(state.conversation===id&&container.isConnected)container.innerHTML=`<div class="error-state" role="alert"><p>${esc(error.message)}</p>${actionButton('open-conversation','Volver a intentar',`data-id="${esc(id)}"`,'small')}</div>`;}
}
async function conversationMode(id,mode,button) {
  button.disabled=true;try{await post(`/api/conversations/${encodeURIComponent(id)}/mode`,{mode});toast(mode==='human'?'Control humano activado.':'Atención automática activada para los próximos mensajes entrantes.');await openConversation(id);}catch(error){toast(error.message);button.disabled=false;}
}

